import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int[] a = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }

        List<Integer> firstHalf = new ArrayList<>();
        List<Integer> secondHalf = new ArrayList<>();
        int splitPoint = n / 2;

        generateFirst(0, 0, a, m, firstHalf, splitPoint);
        generateSecond(splitPoint, 0, a, m, secondHalf, n);

        Set<Integer> firstHalfSet = new HashSet<>(firstHalf);
        List<Integer> uniqueFirstHalf = new ArrayList<>(firstHalfSet);
        Collections.sort(uniqueFirstHalf);

        int bestSum = 0;

        for (int val : secondHalf) {
            int target = m - val;
            int position = Collections.binarySearch(uniqueFirstHalf, target);
            if (position < 0) {
                position = -position - 1;
            }
            if (position > 0) {
                int candidate = uniqueFirstHalf.get(position - 1) + val;
                if (candidate > bestSum) {
                    bestSum = candidate;
                }
            } else {
                if (val > bestSum) {
                    bestSum = val;
                }
            }
        }
        System.out.println(bestSum);
    }

    private static void generateFirst(int i, int total, int[] a, int m, List<Integer> firstHalf, int splitPoint) {
        if (i == splitPoint) {
            firstHalf.add(total);
        } else {
            generateFirst(i + 1, (total + a[i]) % m, a, m, firstHalf, splitPoint);
            generateFirst(i + 1, total, a, m, firstHalf, splitPoint);
        }
    }

    private static void generateSecond(int i, int total, int[] a, int m, List<Integer> secondHalf, int n) {
        if (i == n) {
            secondHalf.add(total);
        } else {
            generateSecond(i + 1, (total + a[i]) % m, a, m, secondHalf, n);
            generateSecond(i + 1, total, a, m, secondHalf, n);
        }
    }
}
